boolean isPalin(String s, int l, int r) {
    if (l >= r) return true;
    if (s.charAt(l) != s.charAt(r)) return false;
    return isPalin(s, l + 1, r - 1);
}

void toh(int n, char from, char to, char aux, List<int[]> moves) {
    if (n == 0) return;
    toh(n - 1, from, aux, to, moves);
    moves.add(new int[]{ n, from - '0', to - '0' });
    toh(n - 1, aux, to, from, moves);
}

// All indices
void collect(int[] A, int B, int i, List<Integer> res) {
    if (i == A.length) return;
    if (A[i] == B) res.add(i);
    collect(A, B, i + 1, res);
}
// First index — return as soon as found
int first(int[] A, int B, int i) {
    if (i == A.length) return -1;
    if (A[i] == B) return i;
    return first(A, B, i + 1);
}
// Last index — recurse first, return the recursive answer if non-(-1)
int last(int[] A, int B, int i) {
    if (i == A.length) return -1;
    int rest = last(A, B, i + 1);
    if (rest != -1) return rest;
    return (A[i] == B) ? i : -1;
}

long power(long a, long n, long mod) {
    if (n == 0) return 1 % mod;
    long half = power(a, n / 2, mod);
    long sq = (half * half) % mod;
    return ((n & 1) == 1) ? (sq * (a % mod)) % mod : sq;
}
